1	// Package relayproof implements cross-chain message verification.
2	package relayproof
3	
4	import (
5		"errors"
6		"fmt"
7		"math"
8		"os"
9		"path/filepath"
10		"sort"
11		"strconv"
12		"sync"
13		"syscall"
14	)
15	
16	// maxProcessTime is the largest legal processing time: non-negative int64
17	// Unix milliseconds, up to the int64 ceiling.
18	const maxProcessTime = math.MaxInt64
19	
20	// Durable queue statuses. Pending and waiting are live; the rest are terminal.
21	const (
22		StatusPending    = "pending"        // accepted, not processed for the first time yet
23		StatusWaiting    = "waiting"        // processed, waiting for a trusted header at proof height
24		StatusSuccess    = "success"        // recorded locally and nonce consumed
25		StatusReplay     = "replay"         // nonce combination already consumed by another message
26		StatusExpired    = "expired"        // absolute expiry reached before delivery
27		StatusUnknownSrc = "unknown-source" // source chain was never registered
28	)
29	
30	// Common errors. Callers can compare with errors.Is.
31	var (
32		// ErrConflict is returned when an id is reused with different message content.
33		ErrConflict = errors.New("message id conflict: existing record has different content")
34		// ErrHeaderConflict is returned when a trusted header is submitted at the
35		// height of the accepted highest trusted header with a different root. The
36		// accepted trusted header is kept and the queue remains usable.
37		ErrHeaderConflict = errors.New("trusted header conflict: different root at the accepted height")
38		// ErrTerminal is returned when re-submitting a terminal id or attempting to
39		// reactivate it.
40		ErrTerminal = errors.New("message is terminal and cannot be reactivated")
41		// ErrInvalidArg is returned for malformed input (empty id, bad times, ...).
42		ErrInvalidArg = errors.New("invalid argument")
43		// ErrLocked is returned when another process holds the state directory open.
44		ErrLocked = errors.New("state directory is locked by another process")
45		// ErrCorrupt is returned when on-disk state is unreadable or unsupported.
46		ErrCorrupt = errors.New("state directory is corrupt or uses an unsupported format")
47		// ErrStorage is returned after a storage failure; the queue must be reopened.
48		ErrStorage = errors.New("storage failure; queue must be reopened")
49	)
50	
51	// Envelope is a submitted message together with its absolute expiry time.
52	type Envelope struct {
53		Message Message
54		// ExpiresAt is an absolute Unix-millisecond instant. Zero means never expire.
55		ExpiresAt int64
56	}
57	
58	// Record is the full persisted state of one submitted message.
59	type Record struct {
60		Msg        Envelope
61		Status     string
62		Reason     string
63		Seq        int64 // submission order, zero-based
64		Attempts   int   // number of processing attempts
65		NextRetry  int64 // 0 when not yet processed, or terminal
66		LastProcAt int64 // processing time of the most recent attempt
67	}
68	
69	// Query is the user-visible view of a Record.
70	type Query struct {
71		ID        string
72		From      string
73		To        string
74		Nonce     uint64
75		Payload   string
76		ProofAt   int64
77		ExpiresAt int64
78		Status    string
79		Reason    string
80		NextRetry int64 // 0 = no retry scheduled (not yet processed, or terminal)
81		Attempts  int
82	}
83	
84	// AdvanceReport is the outcome of one Advance call.
85	type AdvanceReport struct {
86		Now     int64
87		Results []Result
88	}
89	
90	// Result describes what happened to one message during an Advance.
91	type Result struct {
92		ID     string `json:"id"`
93		Status string `json:"status"`
94		Reason string `json:"reason"`
95	}
96	
97	// headerState records the headers seen for one chain: the latest header
98	// written (any trust level) and the highest trusted header accepted. Proof
99	// coverage is determined solely by the highest trusted header — a later
100	// untrusted header, even at a greater height, can never lower or invalidate
101	// it. The zero value is a chain with no recorded headers.
102	type headerState struct {
103		latest  Header
104		trusted *Header
105	}
106	
107	// Queue is a durable local outbox backed by a state directory. A single
108	// Queue owns the directory for writes; other processes attempting to Open the
109	// same directory fail with ErrLocked. It is safe for concurrent use by
110	// multiple goroutines, and a success record plus its nonce consumption commit
111	// as one durable unit.
112	type Queue struct {
113		mu sync.Mutex
114	
115		store  *store
116		flock  *os.File
117		broken bool // a storage write failed; all further mutations fail
118	
119		now      int64                   // last advanced Unix-ms time, 0 = never advanced
120		sources  map[string]bool         // registered source chains
121		headers  map[string]*headerState // per-chain recorded headers (latest + highest trusted)
122		records  map[string]*Record      // by message id
123		order    []string                // non-terminal messages, submission order
124		consumed map[consumeToken]string // (source, destination, nonce) -> successful message id
125		nextSeq  int64
126	}
127	
128	// Open opens (creating if needed) a persistent queue backed by stateDir. It
129	// takes an exclusive process lock on the directory and refuses to start when
130	// the on-disk state is corrupt or in an unsupported format, never clearing it.
131	func Open(stateDir string) (*Queue, error) {
132		if stateDir == "" {
133			return nil, fmt.Errorf("%w: empty state directory", ErrInvalidArg)
134		}
135		if err := os.MkdirAll(stateDir, 0o755); err != nil {
136			return nil, fmt.Errorf("create state directory: %w", err)
137		}
138		abs, err := filepath.Abs(stateDir)
139		if err != nil {
140			return nil, fmt.Errorf("resolve state directory: %w", err)
141		}
142	
143		lockPath := filepath.Join(abs, "lock")
144		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
145		if err != nil {
146			return nil, fmt.Errorf("open lock file: %w", err)
147		}
148		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
149			lock.Close()
150			return nil, fmt.Errorf("%w: %v", ErrLocked, err)
151		}
152	
153		st, state, err := openStore(abs)
154		if err != nil {
155			syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
156			lock.Close()
157			return nil, err
158		}
159	
160		q := &Queue{
161			store:    st,
162			flock:    lock,
163			sources:  state.sources,
164			headers:  state.headers,
165			records:  state.records,
166			consumed: state.consumed,
167			now:      state.now,
168			nextSeq:  state.nextSeq,
169		}
170		q.order = q.reconstructOrder()
171		st.snap = q.snapshot
172		return q, nil
173	}
174	
175	// reconstructOrder returns non-terminal record ids in submission (seq) order.
176	func (q *Queue) reconstructOrder() []string {
177		seqs := make([]int64, 0, len(q.records))
178		live := map[int64]string{}
179		for id, rec := range q.records {
180			if isTerminal(rec.Status) {
181				continue
182			}
183			seqs = append(seqs, rec.Seq)
184			live[rec.Seq] = id
185		}
186		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
187		order := make([]string, 0, len(seqs))
188		for _, seq := range seqs {
189			order = append(order, live[seq])
190		}
191		return order
192	}
193	
194	// snapshot returns a detached copy of live state for log compaction. Callers
195	// must hold mu.
196	func (q *Queue) snapshot() *loadedState {
197		s := &loadedState{
198			sources:  map[string]bool{},
199			headers:  map[string]*headerState{},
200			records:  map[string]*Record{},
201			consumed: map[consumeToken]string{},
202			now:      q.now,
203			nextSeq:  q.nextSeq,
204		}
205		for c := range q.sources {
206			s.sources[c] = true
207		}
208		for c, h := range q.headers {
209			cp := &headerState{latest: h.latest}
210			if h.trusted != nil {
211				t := *h.trusted
212				cp.trusted = &t
213			}
214			s.headers[c] = cp
215		}
216		for id, rec := range q.records {
217			cp := *rec
218			s.records[id] = &cp
219		}
220		for k, v := range q.consumed {
221			s.consumed[k] = v
222		}
223		return s
224	}
225	
226	// Close flushes, releases the directory lock and closes the queue.
227	func (q *Queue) Close() error {
228		q.mu.Lock()
229		defer q.mu.Unlock()
230		if q.flock == nil {
231			return nil
232		}
233		var err error
234		if !q.broken {
235			err = q.store.close()
236		} else {
237			q.store.forceClose()
238		}
239		syscall.Flock(int(q.flock.Fd()), syscall.LOCK_UN)
240		q.flock.Close()
241		q.flock = nil
242		return err
243	}
244	
245	// fail locks in a storage failure: the log tail may be partially written, so
246	// no further appends are allowed in this process (another append would turn a
247	// truncatable torn tail into unrecoverable corruption).
248	func (q *Queue) fail(op string, err error) error {
249		q.broken = true
250		return fmt.Errorf("%w: %s: %v", ErrStorage, op, err)
251	}
252	
253	func (q *Queue) checkWritable() error {
254		if q.flock == nil {
255			return fmt.Errorf("%w: queue is closed", ErrStorage)
256		}
257		if q.broken {
258			return fmt.Errorf("%w: a previous write failed; reopen the queue", ErrStorage)
259		}
260		return nil
261	}
262	
263	// RegisterSource records that messages may originate from chain. Idempotent.
264	func (q *Queue) RegisterSource(chain string) error {
265		if chain == "" {
266			return fmt.Errorf("%w: empty source chain", ErrInvalidArg)
267		}
268		q.mu.Lock()
269		defer q.mu.Unlock()
270		if err := q.checkWritable(); err != nil {
271			return err
272		}
273		if q.sources[chain] {
274			return nil
275		}
276		if err := q.store.appendRegisterSource(chain); err != nil {
277			return q.fail("register source", err)
278		}
279		q.sources[chain] = true
280		return q.maybeCompact()
281	}
282	
283	// UpsertHeader records a header for a chain. The latest header is always
284	// recorded, but proof coverage is determined solely by the highest trusted
285	// header accepted for the chain:
286	//
287	//   - the first trusted header establishes coverage;
288	//   - a higher trusted header advances it;
289	//   - a lower trusted header, or an untrusted header of any height, is
290	//     recorded but can never lower or invalidate established coverage;
291	//   - a trusted header at the current highest trusted height with the same
292	//     root is an idempotent no-op;
293	//   - a trusted header at that height with a different root is an
294	//     ErrHeaderConflict: the accepted trusted header is kept and the queue
295	//     remains usable.
296	//
297	// Header updates never bypass retry scheduling, never process messages, and
298	// never reactivate terminal messages.
299	func (q *Queue) UpsertHeader(h Header) error {
300		if h.Chain == "" {
301			return fmt.Errorf("%w: empty header chain", ErrInvalidArg)
302		}
303		if h.Height < 0 {
304			return fmt.Errorf("%w: negative header height", ErrInvalidArg)
305		}
306		q.mu.Lock()
307		defer q.mu.Unlock()
308		if err := q.checkWritable(); err != nil {
309			return err
310		}
311		hs := q.headers[h.Chain]
312		if hs == nil {
313			hs = &headerState{}
314			q.headers[h.Chain] = hs
315		}
316		if h.Trusted && hs.trusted != nil &&
317			h.Height == hs.trusted.Height && h.Root != hs.trusted.Root {
318			return fmt.Errorf("%w: chain %q height %d: submitted root %q conflicts with accepted root %q",
319				ErrHeaderConflict, h.Chain, h.Height, h.Root, hs.trusted.Root)
320		}
321		if err := q.store.appendHeader(h); err != nil {
322			return q.fail("upsert header", err)
323		}
324		hs.latest = h
325		if h.Trusted && (hs.trusted == nil || h.Height > hs.trusted.Height) {
326			t := h
327			hs.trusted = &t
328		}
329		return q.maybeCompact()
330	}
331	
332	// Submit enqueues a message with an absolute expiry (Unix milliseconds; zero
333	// means never expire). Re-submitting the same id with identical content
334	// returns the existing record without adding a queue entry; the same id with
335	// different content returns ErrConflict and leaves the original untouched;
336	// re-submitting a terminal id returns ErrTerminal. Success is reported only
337	// after the submission is durably persisted.
338	func (q *Queue) Submit(env Envelope) (*Record, error) {
339		m := env.Message
340		if m.ID == "" {
341			return nil, fmt.Errorf("%w: empty message id", ErrInvalidArg)
342		}
343		if m.From == "" || m.To == "" {
344			return nil, fmt.Errorf("%w: empty source or destination chain", ErrInvalidArg)
345		}
346		if m.ProofAt < 0 {
347			return nil, fmt.Errorf("%w: negative proof height", ErrInvalidArg)
348		}
349		if env.ExpiresAt < 0 {
350			return nil, fmt.Errorf("%w: negative expiry time", ErrInvalidArg)
351		}
352	
353		q.mu.Lock()
354		defer q.mu.Unlock()
355		if err := q.checkWritable(); err != nil {
356			return nil, err
357		}
358	
359		if existing, ok := q.records[m.ID]; ok {
360			if isTerminal(existing.Status) {
361				return nil, fmt.Errorf("%w: message %s is %s", ErrTerminal, m.ID, existing.Status)
362			}
363			if sameEnvelope(existing.Msg, env) {
364				out := *existing
365				return &out, nil
366			}
367			return nil, fmt.Errorf("%w: message %s", ErrConflict, m.ID)
368		}
369	
370		rec := &Record{
371			Msg:    env,
372			Status: StatusPending,
373			Reason: "awaiting first processing",
374			Seq:    q.nextSeq,
375		}
376		if err := q.store.appendSubmit(rec); err != nil {
377			return nil, q.fail("submit", err)
378		}
379		q.records[m.ID] = rec
380		q.order = append(q.order, m.ID)
381		q.nextSeq++
382		if err := q.maybeCompact(); err != nil {
383			return nil, err
384		}
385		out := *rec
386		return &out, nil
387	}
388	
389	// Advance moves processing time to nowMs (Unix milliseconds). Equal time may
390	// be advanced repeatedly; going backwards is rejected and changes nothing.
391	//
392	// Each advance, in submission order:
393	//  1. due messages (new messages are due on the next advance; others when now
394	//     has reached their next retry time) are evaluated for replay and expiry,
395	//     replay winning on a tie and now == ExpiresAt counting as expired, then
396	//     for source registration and trusted-header coverage, and finally
397	//     delivered;
398	//  2. afterwards every remaining non-terminal message, regardless of its
399	//     retry schedule, is re-checked for replay and expiry at the new time.
400	//
401	// Unregistered sources are permanently rejected as unknown-source; registered
402	// sources without a trusted header covering the proof height stay waiting and
403	// do not consume the nonce. Waiting retry intervals are 1,2,4,... seconds,
404	// doubling to a 60-second cap, measured from the actual processing time;
405	// jumping over several intervals still costs one attempt.
406	//
407	// The retry instant saturates at the int64 ceiling: a waiting message whose
408	// computed retry would overflow is scheduled for math.MaxInt64 instead, never
409	// a negative, zero or earlier-than-processing instant. Once such a message has
410	// been processed at the ceiling, every later advance is at the same instant,
411	// so it is never due again and keeps its waiting status, reason, attempt
412	// count and ceiling retry time; it is neither reprocessed nor reported again
413	// as a waiting result. Replay and expiry checks, which run independently of
414	// the retry schedule, still apply to it, and a header update alone never
415	// delivers it.
416	func (q *Queue) Advance(nowMs int64) (*AdvanceReport, error) {
417		if nowMs < 0 {
418			return nil, fmt.Errorf("%w: negative processing time", ErrInvalidArg)
419		}
420		q.mu.Lock()
421		defer q.mu.Unlock()
422		if err := q.checkWritable(); err != nil {
423			return nil, err
424		}
425		if q.now != 0 && nowMs < q.now {
426			return nil, fmt.Errorf("%w: processing time %d precedes last advanced time %d", ErrInvalidArg, nowMs, q.now)
427		}
428	
429		report := &AdvanceReport{Now: nowMs}
430	
431		// Phase 1: due messages, first-submission order.
432		for _, id := range append([]string(nil), q.order...) {
433			rec := q.records[id]
434			if rec == nil || isTerminal(rec.Status) {
435				continue
436			}
437			due := rec.Attempts == 0 || retryDue(rec, nowMs)
438			if !due {
439				continue
440			}
441			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
442				return nil, err
443			} else if done {
444				report.Results = append(report.Results, r)
445				continue
446			}
447			r, err := q.processDue(rec, nowMs)
448			if err != nil {
449				return nil, err
450			}
451			report.Results = append(report.Results, r)
452		}
453	
454		// Phase 2: replay/expiry hold for every non-terminal message at the new
455		// time, even while its retry backoff is still running.
456		for _, id := range append([]string(nil), q.order...) {
457			rec := q.records[id]
458			if rec == nil || isTerminal(rec.Status) {
459				continue
460			}
461			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
462				return nil, err
463			} else if done {
464				report.Results = append(report.Results, r)
465			}
466		}
467	
468		if err := q.store.appendAdvance(nowMs); err != nil {
469			return nil, q.fail("advance", err)
470		}
471		q.now = nowMs
472		if err := q.maybeCompact(); err != nil {
473			return nil, err
474		}
475		return report, nil
476	}
477	
478	// maybeCompact rewrites the WAL as a snapshot once it grows past the
479	// threshold. Live state already reflects every acknowledged append, so the
480	// snapshot cannot lose records. A compaction failure is a storage failure:
481	// the queue is marked broken and must be reopened.
482	func (q *Queue) maybeCompact() error {
483		if !q.store.needsCompaction() {
484			return nil
485		}
486		if err := q.store.compact(q.snapshot()); err != nil {
487			return q.fail("compact log", err)
488		}
489		return nil
490	}
491	
492	// checkReplayExpiry terminalizes rec when its nonce was consumed by another
493	// message or its absolute expiry has been reached. Replay wins when both
494	// hold. The bool reports whether the message was terminalized.
495	func (q *Queue) checkReplayExpiry(rec *Record, now int64) (Result, bool, error) {
496		id := rec.Msg.Message.ID
497		token := newConsumeToken(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
498		if winner, taken := q.consumed[token]; taken && winner != id {
499			reason := "nonce combination already consumed by message " + winner
500			r, err := q.applyOutcome(rec, now, terminalOutcome(StatusReplay, reason))
501			if err != nil {
502				return Result{}, false, err
503			}
504			return r, true, nil
505		}
506		if rec.Msg.ExpiresAt != 0 && now >= rec.Msg.ExpiresAt {
507			reason := "expired at " + strconv.FormatInt(rec.Msg.ExpiresAt, 10)
508			r, err := q.applyOutcome(rec, now, terminalOutcome(StatusExpired, reason))
509			if err != nil {
510				return Result{}, false, err
511			}
512			return r, true, nil
513		}
514		return Result{}, false, nil
515	}
516	
517	// processDue classifies a due message against source registration and header
518	// trust, or delivers it.
519	func (q *Queue) processDue(rec *Record, now int64) (Result, error) {
520		m := rec.Msg.Message
521		if !q.sources[m.From] {
522			reason := "unknown source chain " + m.From
523			return q.applyOutcome(rec, now, terminalOutcome(StatusUnknownSrc, reason))
524		}
525		hs := q.headers[m.From]
526		if hs == nil || hs.trusted == nil || hs.trusted.Height < m.ProofAt {
527			cur := int64(0)
528			if hs != nil && hs.trusted != nil {
529				cur = hs.trusted.Height
530			}
531			reason := fmt.Sprintf("waiting for trusted header covering height %d (current %d)", m.ProofAt, cur)
532			return q.applyOutcome(rec, now, waitingOutcome(reason))
533		}
534	
535		// Deliver: success record and nonce consumption are one log entry. The
536		// coverage height is the highest trusted header actually accepted — never
537		// a higher untrusted header.
538		token := newConsumeToken(m.From, m.To, m.Nonce)
539		reason := "delivered; proof verified by trusted header at height " + strconv.FormatInt(hs.trusted.Height, 10)
540		return q.applyOutcome(rec, now, successOutcome(reason, token))
541	}
542	
543	// outcome describes one processing result independently of which path found
544	// it: waiting for header coverage, delivery, or one of the terminal rejections
545	// (replay, expiry, unknown source). It carries only the business differences
546	// between the result kinds; the rules shared by every result — one more
547	// attempt, the processing-time stamp, how the result is persisted and when the
548	// record may change — live solely in applyOutcome.
549	type outcome struct {
550		status string
551		reason string
552		// consume is set only for success: the message's own
553		// (source, destination, nonce) triple, attributed to that message. No
554		// other result kind consumes a nonce.
555		consume *consumeToken
556		// op labels the failing operation in the storage error for this kind of
557		// result, keeping each path's historical error wording.
558		op string
559	}
560	
561	// waitingOutcome keeps the message live with its status unchanged in kind and
562	// its existing backoff machinery: the actual retry instant is computed by
563	// applyOutcome from the processing time and the new attempt number.
564	func waitingOutcome(reason string) outcome {
565		return outcome{status: StatusWaiting, reason: reason, op: "schedule retry"}
566	}
567	
568	// terminalOutcome settles a non-success result that ends processing: replay,
569	// expiry or unknown-source. Such results clear the retry schedule, consume no
570	// nonce and leave the live processing order.
571	func terminalOutcome(status, reason string) outcome {
572		return outcome{status: status, reason: reason, op: "terminalize"}
573	}
574	
575	// successOutcome delivers the message: it clears the retry schedule, leaves
576	// the processing order and records consumption of the message's own triple,
577	// attributed to the message itself, in the same durable record as the success
578	// state.
579	func successOutcome(reason string, token consumeToken) outcome {
580		return outcome{status: StatusSuccess, reason: reason, consume: &token, op: "deliver"}
581	}
582	
583	// applyOutcome is the single path through which every processing result is
584	// saved and takes effect. It persists the result first and touches the record
585	// only after the save is acknowledged, so a failed write changes nothing: the
586	// message keeps its previous status, reason, attempt count, processing time
587	// and retry schedule, its nonce is not consumed, and earlier results already
588	// acknowledged in the same advance stay in force. On success every result
589	// counts exactly one more attempt and stamps LastProcAt with the processing
590	// time; a waiting result additionally keeps its saturated backoff schedule,
591	// while success and terminal results clear the retry time and leave the
592	// processing order; success also records the nonce consumption.
593	func (q *Queue) applyOutcome(rec *Record, now int64, oc outcome) (Result, error) {
594		id := rec.Msg.Message.ID
595		attempt := rec.Attempts + 1
596		nextRetry := int64(0)
597		if oc.status == StatusWaiting {
598			nextRetry = nextRetryAt(now, attempt)
599		}
600		if err := q.store.appendOutcome(now, rec, attempt, nextRetry, oc); err != nil {
601			return Result{}, q.fail(oc.op, err)
602		}
603		rec.Attempts = attempt
604		rec.LastProcAt = now
605		rec.Status = oc.status
606		rec.Reason = oc.reason
607		rec.NextRetry = nextRetry
608		if oc.consume != nil {
609			q.consumed[*oc.consume] = id
610		}
611		if isTerminal(oc.status) {
612			q.removeFromOrder(id)
613		}
614		return Result{ID: id, Status: oc.status, Reason: oc.reason}, nil
615	}
616	
617	// retryDue reports whether a waiting record's next retry is reached at now.
618	// Backoff delays are always positive, so every representable retry lies
619	// strictly after the processing time that scheduled it; a waiting message is
620	// therefore evaluated at most once per distinct processing time. The only
621	// instant where the retry cannot lie later is the int64 ceiling: there the
622	// schedule saturates to the ceiling itself. Once the message was processed at
623	// the ceiling, every legal advance is at the same instant, so the retry can
624	// never be reached "later" — treating equal time as due would reprocess the
625	// message on every advance, inflate attempts and re-report waiting forever.
626	func retryDue(rec *Record, now int64) bool {
627		if now < rec.NextRetry {
628			return false
629		}
630		return now != rec.LastProcAt
631	}
632	
633	func (q *Queue) removeFromOrder(id string) {
634		for i, cand := range q.order {
635			if cand == id {
636				q.order = append(q.order[:i], q.order[i+1:]...)
637				return
638			}
639		}
640	}
641	
642	// nextRetryAt returns the retry instant after the attempt-th processing at
643	// now: now plus the backoff delay, saturated at math.MaxInt64. Saturation
644	// keeps the scheduled retry non-negative, never zero (when processed at a
645	// positive time) and never earlier than the processing time; when the true
646	// retry overflows int64 the ceiling is the nearest representable instant.
647	func nextRetryAt(now int64, attempt int) int64 {
648		delay := nextRetryDelay(attempt)
649		if now > maxProcessTime-delay {
650			return maxProcessTime // now+delay would overflow; delay is at most 60000
651		}
652		return now + delay
653	}
654	
655	// nextRetryDelay is the backoff after the attempt-th processing (1-based):
656	// 1s, 2s, 4s, 8s, 16s, 32s, then 60s capped, in milliseconds.
657	func nextRetryDelay(attempt int) int64 {
658		if attempt < 1 {
659			attempt = 1
660		}
661		if attempt > 6 {
662			return 60_000
663		}
664		return int64(1) << (attempt - 1) * 1000
665	}
666	
667	func isTerminal(status string) bool {
668		switch status {
669		case StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
670			return true
671		}
672		return false
673	}
674	
675	func sameEnvelope(a, b Envelope) bool {
676		return a.ExpiresAt == b.ExpiresAt &&
677			a.Message.ID == b.Message.ID &&
678			a.Message.From == b.Message.From &&
679			a.Message.To == b.Message.To &&
680			a.Message.Nonce == b.Message.Nonce &&
681			a.Message.Payload == b.Message.Payload &&
682			a.Message.ProofAt == b.Message.ProofAt
683	}
684	
685	// Query returns the current state of a message.
686	func (q *Queue) Query(id string) (Query, bool) {
687		q.mu.Lock()
688		defer q.mu.Unlock()
689		rec, ok := q.records[id]
690		if !ok {
691			return Query{}, false
692		}
693		return toQuery(rec), true
694	}
695	
696	// Queries returns all records in first-submission order.
697	func (q *Queue) Queries() []Query {
698		q.mu.Lock()
699		defer q.mu.Unlock()
700		out := make([]Query, 0, len(q.records))
701		for _, rec := range q.records {
702			out = append(out, toQuery(rec))
703		}
704		sort.Slice(out, func(i, j int) bool {
705			return q.records[out[i].ID].Seq < q.records[out[j].ID].Seq
706		})
707		return out
708	}
709	
710	// Now returns the last advanced processing time, or 0 if never advanced.
711	func (q *Queue) Now() int64 {
712		q.mu.Lock()
713		defer q.mu.Unlock()
714		return q.now
715	}
716	
717	func toQuery(rec *Record) Query {
718		return Query{
719			ID:        rec.Msg.Message.ID,
720			From:      rec.Msg.Message.From,
721			To:        rec.Msg.Message.To,
722			Nonce:     rec.Msg.Message.Nonce,
723			Payload:   rec.Msg.Message.Payload,
724			ProofAt:   rec.Msg.Message.ProofAt,
725			ExpiresAt: rec.Msg.ExpiresAt,
726			Status:    rec.Status,
727			Reason:    rec.Reason,
728			NextRetry: rec.NextRetry,
729			Attempts:  rec.Attempts,
730		}
731	}
732

